package glitch

import data.glitch_lib

iam_action_names := {"Action", "Resource", "Principal"}
compute_runas_names := {"RunAsUser", "RunAsNonRoot", "Privileged", "Capabilities"}
db_storage_names := {"PublicAccess", "Privileges", "Permissions", "DeletionPolicy"}
network_names := {"CidrBlock", "FromPort", "ToPort"}

wildcard_patterns := {"*", "iam:*", "admin:*", "*:*"}
admin_roles := {"Owner", "Admin", "root", "AdministratorAccess"}
root_values := {0, "0", "root"}
privileged_values := {true, "true"}
all_capabilities := {"ALL", "all"}
public_access_values := {true, "true"}
superuser_values := {"ALL", "SUPERUSER", "all", "superuser"}
retention_values := {"Retain", "retain"}
open_cidr := {"0.0.0.0/0", "::/0"}
admin_ports := {22, 3389, 1433, 3306}

check_wildcard(value) {
    value.ir_type == "String"
    regex.match("(\\*|iam:\\*|admin:\\*|\\*:\\*)", value.value)
}

check_admin_role(value) {
    value.ir_type == "String"
    role := lower(value.value)
    role == admin_roles[_]
}

check_root(value) {
    value.ir_type == "Integer"
    value.value == 0
} else {
    value.ir_type == "String"
    lower(value.value) == "root"
}

check_privileged(value) {
    value.ir_type == "Boolean"
    value.value == true
}

check_all_capability(value) {
    value.ir_type == "String"
    lower(value.value) == "all"
}

check_public_access(value) {
    value.ir_type == "Boolean"
    value.value == true
}

check_superuser(value) {
    value.ir_type == "String"
    lower(value.value) == "all"
} else {
    value.ir_type == "String"
    lower(value.value) == "superuser"
}

check_retention(value) {
    value.ir_type == "String"
    lower(value.value) == "retain"
}

check_open_cidr(value) {
    value.ir_type == "String"
    value.value == "0.0.0.0/0"
} else {
    value.ir_type == "String"
    value.value == "::/0"
}

check_admin_port(value) {
    value.ir_type == "Integer"
    admin_ports[value.value]
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    iam_action_names[attr.name]
    check_wildcard(attr.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Wildcard permission detected in IAM configuration - Overly permissive actions grant unnecessary privileges. (CWE-250)"
    }
}

